#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to;
    bool adjustable;
    int idx; // index of adjustable edge if adjustable
    long long w; // fixed weight for fixed edges
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;
    int s1, s2, f;
    cin >> s1 >> s2 >> f;

    vector<vector<Edge>> adj(n+1);
    vector<long long> li(k), ri(k);

    // fixed edges
    for(int i = 0; i < m; ++i){
        int a,b; long long c;
        cin >> a >> b >> c;
        Edge e; e.to = b; e.adjustable = false; e.idx = -1; e.w = c;
        adj[a].push_back(e);
    }
    // adjustable edges
    for(int i = 0; i < k; ++i){
        int a,b; long long l,r;
        cin >> a >> b >> l >> r;
        li[i] = l; ri[i] = r;
        Edge e; e.to = b; e.adjustable = true; e.idx = i; e.w = 0;
        adj[a].push_back(e);
    }

    auto dijkstra_with = [&](int src, bool use_li)-> long long {
        const long long INF = (1LL<<62);
        vector<long long> dist(n+1, INF);
        dist[src] = 0;
        using P = pair<long long,int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        pq.push({0, src});
        while(!pq.empty()){
            auto [d,u] = pq.top(); pq.pop();
            if(d != dist[u]) continue;
            for(const auto &e : adj[u]){
                long long w = 0;
                if(e.adjustable){
                    w = use_li ? li[e.idx] : ri[e.idx];
                } else {
                    w = e.w;
                }
                if(dist[e.to] > d + w){
                    dist[e.to] = d + w;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        return dist[f];
    };

    long long d1_min = dijkstra_with(s1, true);
    long long d2_min = dijkstra_with(s2, true);
    long long d2_max = dijkstra_with(s2, false);

    string ans;
    vector<long long> assign(k, 0);
    if(d1_min < d2_min){
        ans = "WIN";
        for(int i=0;i<k;++i) assign[i] = li[i];
    } else if(d1_min > d2_max){
        ans = "LOSE";
    } else {
        ans = "DRAW";
        for(int i=0;i<k;++i) assign[i] = li[i];
    }

    cout << ans << "\n";
    if(ans != "LOSE"){
        for(int i=0;i<k;++i){ if(i) cout << ' '; cout << assign[i]; }
        cout << "\n";
    }

    return 0;
}
